@once
<style>
.erp-assistant{font-size:14px;color:#19374f}.erp-assistant *{box-sizing:border-box}.erp-assistant h1,.erp-assistant h2,.erp-assistant p{margin:0}.erp-assistant [hidden]{display:none!important}.erp-assistant.ea-page{max-width:1120px;margin:auto;padding:28px 24px 40px}.erp-assistant .ea-hero{display:flex;align-items:center;justify-content:space-between;gap:20px;background:linear-gradient(120deg,#142f45,#245775);padding:28px 30px;border-radius:18px;color:white;margin-bottom:20px}.erp-assistant .ea-hero small{font-size:10px;font-weight:700;letter-spacing:1.7px;color:#a2dfe6}.erp-assistant h1{font-size:29px;font-weight:750;margin:7px 0}.erp-assistant .ea-hero p{font-size:13px;color:#d3e4ee}.erp-assistant .ea-privacy{font-size:11px;padding:9px 12px;border-radius:8px;background:#ffffff12;border:1px solid #ffffff25;max-width:170px}.erp-assistant .ea-panel{display:flex;flex-direction:column;background:#fff;border:1px solid #d9e6ef;border-radius:16px;overflow:hidden;box-shadow:0 5px 20px #173c5710}.erp-assistant .ea-top{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:17px 20px;background:#f5f9fc;border-bottom:1px solid #e1ebf3}.erp-assistant .ea-top strong{font-size:15px;color:#234f6d}.erp-assistant .ea-top small{font-size:10px;display:block;color:#6a8398;margin-top:4px}.erp-assistant .ea-controls{display:flex;gap:6px;align-items:center}.erp-assistant .ea-controls button,.erp-assistant .ea-controls a{display:inline-flex;align-items:center;justify-content:center;min-width:32px;height:32px;background:white;border:1px solid #d2e0ec;border-radius:8px;color:#41627e;font-size:19px;text-decoration:none;cursor:pointer}.erp-assistant .ea-prompts{display:flex;gap:7px;flex-wrap:wrap;padding:13px 18px;border-bottom:1px solid #eef3f7}.erp-assistant .ea-prompts button{border:1px solid #d4e4ef;border-radius:20px;padding:6px 10px;background:#fff;color:#41647f;font-size:11px;font-weight:600;cursor:pointer}.erp-assistant .ea-prompts button:hover{background:#edf5fb}.erp-assistant .ea-conversation{padding:20px;overflow-y:auto;min-height:280px;max-height:65vh;background:#fafcfe;scroll-behavior:smooth}.erp-assistant .ea-welcome{text-align:center;max-width:520px;margin:35px auto;color:#58768e}.erp-assistant .ea-welcome>span{display:inline-grid;place-items:center;width:48px;height:48px;border-radius:14px;background:#e5f1fa;color:#245f8b;font-size:28px}.erp-assistant h2{font-size:21px;font-weight:700;color:#2c516c;margin:17px 0 10px}.erp-assistant .ea-welcome p{font-size:13px;line-height:1.8}.erp-assistant .ea-welcome .ea-hint{font-size:11px;color:#7a91a4;margin-top:14px}.erp-assistant .ea-user{margin:10px 0 14px auto;width:fit-content;max-width:90%;padding:11px 15px;background:#255a8b;color:white;border-radius:12px 12px 2px 12px;white-space:pre-wrap;overflow-wrap:anywhere;font-size:13px}.erp-assistant .ea-reply{margin:0 0 20px;background:#fff;border:1px solid #e0eaf2;border-radius:12px;padding:17px}.erp-assistant .ea-speaker{font-size:10px;letter-spacing:.6px;text-transform:uppercase;color:#6789a2;font-weight:700;margin-bottom:9px}.erp-assistant .ea-answer{font-size:14px;line-height:1.8;color:#244860}.erp-assistant .ea-asof{font-size:10px;color:#7b92a4;margin:6px 0 14px}.erp-assistant .ea-task{margin-top:12px;background:#f7fafc;border:1px solid #dfeaf3;border-radius:10px;padding:14px}.erp-assistant .ea-task-head{display:flex;justify-content:space-between;align-items:start;gap:12px}.erp-assistant .ea-task-head strong{font-size:13px;line-height:1.6}.erp-assistant .ea-count{border-radius:8px;background:#e4eff8;color:#285a80;padding:4px 9px;font-size:15px;min-width:30px;text-align:center}.erp-assistant .ea-task>p{font-size:12px;line-height:1.8;color:#56738b;margin:8px 0}.erp-assistant .ea-overdue{font-size:10px;color:#ac6023;background:#fff0dd;border-radius:5px;display:inline-block;padding:4px 7px;margin-top:5px}.erp-assistant .ea-sample{border-top:1px solid #e4edf5;padding:9px 0;font-size:12px}.erp-assistant .ea-sample a{color:#2f6088;text-decoration:none;overflow-wrap:anywhere}.erp-assistant .ea-sample small{font-size:10px;display:block;color:#718ba1;margin-top:4px}.erp-assistant .ea-sample .ea-late{color:#ad6427}.erp-assistant .ea-review{font-size:11px;display:inline-block;color:#255f8e;text-decoration:none;font-weight:700;padding:7px 0}.erp-assistant .ea-review:hover{text-decoration:underline}.erp-assistant .ea-scope,.erp-assistant .ea-engine{display:block;font-size:10px;color:#7a91a3;line-height:1.7;margin-top:13px}.erp-assistant .ea-engine{margin-top:5px}.erp-assistant .ea-partial{background:#fff5df;color:#946321;padding:10px;border-radius:7px;font-size:12px;line-height:1.7;margin-top:12px}.erp-assistant .ea-status{font-size:11px;line-height:1.6;color:#926126;padding:0 18px;background:white}.erp-assistant .ea-status:not(:empty){padding-top:12px;padding-bottom:4px}.erp-assistant .ea-compose{display:flex;align-items:center;gap:10px;padding:14px 18px 8px;border-top:1px solid #e7eef5;background:#fff}.erp-assistant .ea-compose input{min-width:0;flex:1;border:1px solid #cbdce9;border-radius:9px;padding:11px 13px;min-height:43px;color:#24445e;font:inherit;background:#fff;font-size:13px}.erp-assistant .ea-compose button{padding:11px 15px;min-height:43px;border-radius:9px;border:0;background:#285f8b;color:white;font-size:13px;font-weight:700;cursor:pointer}.erp-assistant button:disabled{opacity:.5;cursor:wait}.erp-assistant .ea-footnote{font-size:10px;text-align:center;color:#7d93a4;line-height:1.6;padding:3px 16px 13px}.erp-assistant .ea-sr-only{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.erp-assistant button:focus-visible,.erp-assistant a:focus-visible,.erp-assistant input:focus-visible{outline:3px solid #70b5e7;outline-offset:2px}.erp-assistant.ea-floating{position:fixed;right:22px;bottom:22px;z-index:80}.erp-assistant .ea-launch{display:flex;align-items:center;gap:9px;padding:12px 18px;border-radius:25px;background:#174f75;color:#fff;border:1px solid #4381a5;box-shadow:0 5px 22px #183d5540;font-size:13px;font-weight:700;cursor:pointer}.erp-assistant .ea-launch>span:first-child{font-size:20px;color:#b4e8ec}.erp-assistant .ea-launch b{background:#e4ad47;color:#362508;border-radius:12px;min-width:23px;padding:3px 6px;font-size:11px}.erp-assistant .ea-widget-panel{position:absolute;right:0;bottom:61px;width:440px;max-width:calc(100vw - 28px);box-shadow:0 12px 50px #15364b35;border-radius:16px}.erp-assistant .ea-widget-panel .ea-conversation{min-height:200px;max-height:min(52vh,480px);padding:13px}.erp-assistant .ea-widget-panel .ea-top{padding:13px 16px}.erp-assistant .ea-widget-panel .ea-prompts{padding:11px 13px;gap:5px}.erp-assistant .ea-widget-panel .ea-prompts button{font-size:10px;padding:5px 9px}.erp-assistant .ea-widget-panel .ea-reply{padding:13px}.erp-assistant .ea-widget-panel .ea-task{padding:11px}.erp-assistant .ea-widget-panel .ea-compose{padding:12px 13px 7px;gap:7px}
@media(max-width:650px){.erp-assistant.ea-page{padding:18px 12px}.erp-assistant .ea-hero{padding:23px;align-items:start;flex-direction:column}.erp-assistant h1{font-size:25px}.erp-assistant .ea-privacy{max-width:none}.erp-assistant .ea-conversation{padding:13px}.erp-assistant .ea-reply{padding:13px}.erp-assistant.ea-floating{right:14px;bottom:14px}.erp-assistant .ea-widget-panel{bottom:57px}.erp-assistant .ea-widget-panel .ea-conversation{max-height:45vh}.erp-assistant .ea-compose input{font-size:16px}.erp-assistant .ea-launch{padding:10px 15px}}
</style>
@endonce
